import{_ as n,o as i,c as a,ai as e}from"./chunks/framework.Ai2o9gNv.js";const c=JSON.parse('{"title":"30-枚举","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/30-枚举/30-枚举.md","filePath":"仓颉入门到实战/30-枚举/30-枚举.md","lastUpdated":1735519860000,"__rawMarkdown":"# 30-枚举\\n\\n`enum` 类型提供了通过列举一个类型的所有可能取值来定义此类型的方式，比如：\\n\\n1. 星期一到星期日可以是一种枚举\\n2. 不同的颜色的组成可以是一种枚举\\n3. 观看的电影列表可以是一种枚举\\n\\n## enum 的定义\\n\\n定义 `enum` 时需要把它所有可能的取值一一列出，我们称这些值为 `enum` 的构造器（或者 `constructor`）。\\n\\n```javascript\\nenum RGBColor {\\n    | Red | Green | Blue\\n}\\n```\\n\\n**enum** 是定义枚举的关键字， **RGBColor**  是这种枚举的名称， **Red** 、**Green** 、 **Blue** 是枚举中可选的值。他们以 **|** 作为分割，其中 **Red**前面的**|** 是可选的\\n\\n```javascript\\nenum RGBColor {\\n    Red | Green | Blue\\n}\\n```\\n\\n## enum的构造器\\n\\n`enum` 中的构造器还可以携带若干（至少一个）参数，称为有参构造器。比如`enum` 中的构造器还可以携带若干（至少一个）参\\n\\n数，称为有参构造器\\n\\n```javascript\\nenum RGBColor {\\n    | Red(UInt8) | Green(UInt8) | Blue(UInt8)\\n}\\n```\\n\\n## `enum` 支持递归定义\\n\\n```javascript\\nenum Expr {\\n    | Num(Int64)\\n    | Add(Expr, Expr)\\n    | Sub(Expr, Expr)\\n}\\n\\nmain() {\\n    let a = Expr.Add(Expr.Num(23), Expr.Num(Int64(42)))\\n}\\n```\\n\\n## `enum` 定义成员函数、操作符函数\\n\\n但是要求构造器、成员函数、成员属性之间不能重名\\n\\n```javascript\\nenum RGBColor {\\n    | Red | Green | Blue\\n\\n    public static func printType() {\\n        print(\\"RGBColor\\")\\n    }\\n}\\n```\\n\\n## enum 的使用\\n\\n定义了 `enum` 类型之后，就可以创建此类型的实例（即 `enum` 值），`enum` 值只能取 `enum` 类型定义中的一个构造器。`enum` \\n\\n没有构造函数，可以通过 `类型名.构造器`，或者直接使用构造器的方式来构造一个 `enum` 值（对于有参构造器，需要传实参）\\n\\n```javascript\\nenum RGBColor {\\n    | Red | Green | Blue(UInt8)\\n}\\n\\nmain() {\\n    let r = RGBColor.Red\\n    let g = Green\\n    let b = Blue(100)\\n}\\n```\\n\\n当省略类型名时，`enum` 构造器的名字可能和类型名、变量名、函数名发生冲突。此时必须加上 `enum` 类型名来使用 `enum` 构造\\n\\n器，否则只会选择同名的类型、变量、函数定义。\\n\\n下面的例子中，只有构造器 `Blue(UInt8)` 可以不带类型名使用，`Red` 和 `Green(UInt8)` 皆会因为名字冲突而不能直接使用，\\n\\n必须加上类型名 `RGBColor`。\\n\\n```javascript\\nlet Red = 1\\n\\nfunc Green(g: UInt8) {\\n    return g\\n}\\n\\nenum RGBColor {\\n    | Red | Green(UInt8) | Blue(UInt8)\\n}\\n\\nlet r1 = Red                 // Will choose \'let Red\'\\nlet r2 = RGBColor.Red        // Ok: constructed by enum type name\\n\\nlet g1 = Green(100)          // Will choose \'func Green\'\\nlet g2 = RGBColor.Green(100) // Ok: constructed by enum type name\\n\\nlet b = Blue(100)            // Ok: can be uniquely identified as an enum constructor\\n```\\n\\n如下的例子中，只有构造器 `Blue` 会因为名称冲突而不能直接使用，必须加上类型名 `RGBColor`。\\n\\n```javascript\\nclass Blue {}\\n\\nenum RGBColor {\\n    | Red | Green(UInt8) | Blue(UInt8)\\n}\\n\\nlet r = Red                 // Ok: constructed by enum type name\\n\\nlet g = Green(100)          // Ok: constructed by enum type name\\n\\nlet b = Blue(100)           // Will choose constructor of \'class Blue\' and report an error\\n```"}'),l={name:"仓颉入门到实战/30-枚举/30-枚举.md"};function p(t,s,h,r,k,d){return i(),a("div",null,[...s[0]||(s[0]=[e("",28)])])}const u=n(l,[["render",p]]);export{c as __pageData,u as default};
